		counter packets 789 bytes 48690 jump OVN-KUBE-EXTERNALIP
		counter packets 789 bytes 48690 jump OVN-KUBE-NODEPORT
		counter packets 789 bytes 48690 jump OVN-KUBE-ITP
	}

	chain PREROUTING {
		type nat hook prerouting priority dstnat; policy accept;
		counter packets 303 bytes 45761 jump OVN-KUBE-ETP
		counter packets 303 bytes 45761 jump OVN-KUBE-EXTERNALIP
		counter packets 303 bytes 45761 jump OVN-KUBE-NODEPORT
	}
}
